const C = require('crypto-js');
test("utf8 and base64", () => {
  const words = C.enc.Utf8.parse("hällo wörld");
  expect(C.enc.Base64.stringify(words)).to.equal("aMOkbGxvIHfDtnJsZA==");
  expect(C.enc.Base64.parse("aMOkbGxvIHfDtnJsZA==").toString(C.enc.Utf8)).to.equal("hällo wörld");
  expect(words.sigBytes).to.equal(13);
});
test("hex and latin1", () => {
  expect(C.enc.Hex.parse("48656c6c6f").toString(C.enc.Latin1)).to.equal("Hello");
  expect(C.enc.Latin1.parse("Hi").toString()).to.equal("4869");
  expect(C.enc.Base64url.stringify(C.enc.Hex.parse("fbff"))).to.equal("-_8");
});
test("concat", () => {
  const a = C.enc.Utf8.parse("ab");
  a.concat(C.enc.Utf8.parse("c"));
  expect(C.SHA256(a).toString()).to.equal(C.SHA256("abc").toString());
});
